pub fn signed_view_disagreement_message(reason: Rc<SignedViewDisagreement>) -> String {
    match (*reason.clone()).clone() {
    SignedViewDisagreement::SignedCarrierNotACoproduct => "its row declares a signed view, which names two constructors, and the declaration is not a coproduct (it is opaque, an alias or a product)".to_string(),
    SignedViewDisagreement::SignedArity { constructor_count: c, .. } => v1_rt::concat("its row declares a signed view, which folds exactly two constructors, and the declaration has ".to_string(), (c.clone()).to_string()),
    SignedViewDisagreement::SignedArmsCoincide { constructor: c, .. } => v1_rt::concat(v1_rt::concat("its row names `".to_string(), c.clone()), "` as both the non-negative and the negative constructor".to_string()),
    SignedViewDisagreement::SignedArmNotDeclared { constructor: c, .. } => v1_rt::concat(v1_rt::concat("its row names the constructor `".to_string(), c.clone()), "`, which the declaration does not declare".to_string()),
    SignedViewDisagreement::SignedArmPayloadNotSole { constructor: c, payload: f, .. } => v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("its row names `".to_string(), f.clone()), "` as the payload of `".to_string()), c.clone()), "`, which is not that constructor's one field".to_string()),
    SignedViewDisagreement::SignedPayloadNotNatural { constructor: c, payload: f, .. } => v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("the payload `".to_string(), f.clone()), "` of `".to_string()), c.clone()), "` is not declared at a grounded natural carrier (a Peano view whose range starts at 0)".to_string()),
    SignedViewDisagreement::SignedPayloadsDiffer => "its two signed arms' payloads are declared at different natural carriers".to_string(),
}
}

